// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PuttyV2} from "../src/PuttyV2.sol";

contract InvMutTest is Test {
    PuttyV2 c;
    FakeERC20 token;
    ERC1271Maker maker;

    function setUp() public {
        c = new PuttyV2("", 0, address(this));
        token = new FakeERC20();
        maker = new ERC1271Maker();
    }

    function testFuzz_property(
        uint256 premium,
        uint256 strike,
        uint256 duration,
        uint256 expiration,
        bool isCall
    ) public {
        duration = bound(duration, 0, 10_000 days - 1);
        expiration = bound(expiration, block.timestamp + 1, type(uint256).max / 2);
        premium = bound(premium, 0, type(uint128).max);
        strike = bound(strike, 0, type(uint128).max);
        vm.warp(expiration - 1);

        address[] memory whitelist = new address[](0);
        address[] memory floorTokens = new address[](0);
        PuttyV2.ERC20Asset[] memory erc20Assets = new PuttyV2.ERC20Asset[](0);
        PuttyV2.ERC721Asset[] memory erc721Assets = new PuttyV2.ERC721Asset[](0);

        PuttyV2.Order memory order = PuttyV2.Order({
            maker: address(maker),
            isCall: isCall,
            isLong: true,
            baseAsset: address(token),
            strike: strike,
            premium: premium,
            duration: duration,
            expiration: expiration,
            nonce: 0,
            whitelist: whitelist,
            floorTokens: floorTokens,
            erc20Assets: erc20Assets,
            erc721Assets: erc721Assets
        });

        bytes memory signature = new bytes(0);
        uint256[] memory floorAssetTokenIds = new uint256[](0);

        c.fillOrder(order, signature, floorAssetTokenIds);

        bytes32 oppositeId = c.hashOppositeOrder(order);

        // General rule: after filling a LONG order, only the long position id carries an
        // expiration; the opposite (short) position id must have expiration 0.
        assertTrue(c.positionExpirations(uint256(oppositeId)) == 0);
    }
}

contract FakeERC20 {
    function transferFrom(address, address, uint256) external returns (bool) {
        return true;
    }
}

contract ERC1271Maker {
    function isValidSignature(bytes32, bytes memory) external pure returns (bytes4) {
        return 0x1626ba7e;
    }
}
